namespace ghidra.framework.options;







using org.apache.commons.io;

using ghidra.util;
using ghidra.util;
using ghidra.util.classfinder;

public class FileOptions : AbstractOptions {

	private File file;

	public FileOptions(string name) : base(name)
    {
	}

	public FileOptions(File file)
    : this(FilenameUtils.getBaseName(file.getName()))
    {
		this.file = file;
		loadFromFile();
	}

	public void save(File saveFile)
    {
		this.name = FilenameUtils.getBaseName(saveFile.getName());
		this.file = saveFile;
		saveToFile();
	}

	public File getFile() {
		return file;
	}

	public CustomOption readCustomOption(GProperties properties) {
		string customOptionClassName = properties.getString("CUSTOM_OPTION_CLASS", null);
		try {
			Class<CustomOption> c = ClassSearcher.forNameSafe(customOptionClassName,
				typeof(CustomOption), getClass().getClassLoader());
			CustomOption customOption = c.getDeclaredConstructor().newInstance();
			customOption.readState(properties);
			return customOption;
		}
		catch (Exception e) {
			Msg.error(this, "Can't create customOption instance for: " + customOptionClassName, e);
		}
		return null;
	}

	private void loadFromFile()
    {
		GProperties properties = new JSonProperties(file);
		foreach (string optionName in properties.getNames()) {
			object @object = properties.getObject(optionName);
			if (@object is GProperties customState) {
				@object = readCustomOption(customState);
			}
			Option option =
				createUnregisteredOption(optionName, OptionType.getOptionType(@object), null);
			option.doSetCurrentValue(@object);  // use doSet versus set so that it is not registered
			valueMap.put(optionName, option);
		}
	}

	private void saveToFile()
    {
		SaveState saveState = new SaveState("File_Options");

		foreach (string optionName in valueMap.keySet()) {
			Option optionValue = valueMap.get(optionName);
			if (!optionValue.isDefault()) {
				object value = optionValue.getValue(null);
				if (value is CustomOption) {
					SaveState customState = new SaveState();
					customState.putString("CUSTOM_OPTION_CLASS", value.GetType().getName());
					((CustomOption) value).writeState(customState);
					value = customState;
				}
				saveState.putObject(optionName, value);
			}
		}
		saveState.saveToJsonFile(file);
	}

	/* @Override */
	protected Option createRegisteredOption(string optionName, OptionType type, string description,
			HelpLocation help, object defaultValue, PropertyEditor editor) {
		return new FileOption(optionName, type, description, help, defaultValue, true, editor);
	}

	/* @Override */
	protected Option createUnregisteredOption(string optionName, OptionType type,
			object defaultValue) {

		if (type == OptionType.KEYSTROKE_TYPE) {
			// convert key strokes to action triggers
			type = OptionType.ACTION_TRIGGER;
			if (defaultValue is KeyStroke keyStroke) {
				defaultValue = new ActionTrigger(keyStroke);
			}
		}

		return new FileOption(optionName, type, null, null, defaultValue, false, null);
	}

	/* @Override */
	protected bool notifyOptionChanged(string optionName, object oldValue, object newValue) {
		// do nothing for now
		return true;
	}

	private static class FileOption : Option {
		private object currentValue;

		FileOption(string name, OptionType type, string description, HelpLocation helpLocation,
				object defaultValue, bool isRegistered, PropertyEditor editor) : base(name, type, description, helpLocation, defaultValue, isRegistered, editor)
    {

			this.currentValue = defaultValue;
		}

		/* @Override */
		public object getCurrentValue() {
			return currentValue;
		}

		/* @Override */
		public void doSetCurrentValue(object value) {
			currentValue = value;
		}
	}

	/* @Override */
	public string toString() {
		return name;
	}

	public FileOptions copy() {
		FileOptions copy = new FileOptions("new");

		foreach (string optionName in valueMap.keySet()) {
			Option optionValue = valueMap.get(optionName);
			if (!optionValue.isDefault()) {
				object value = optionValue.getValue(null);
				copy.putObject(optionName, value);
			}
		}

		return copy;
	}
}
